export default function LabeledCheckbox({ id, label, checked, onChange }) {
  return (
    <div className="CheckboxGroup">
      <input
        type="checkbox"
        id={id}
        checked={checked}
        onChange={onChange}
        className="CustomCheckboxInput"
      />

      <label htmlFor={id} className="CustomCheckboxWrapper">
        <span className="CustomCheckboxBox">
          {checked && <img src="/icons/check.svg" alt="✔" className="CheckmarkIcon" />}
        </span>
        <span className="CheckboxLabel">{label}</span>
      </label>
    </div>
  );
}
